1	 // @ts-nocheck
2	// deno-lint-ignore-file no-explicit-any
3	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
4	import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
5	import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
6	
7	const corsHeaders = {
8	  "Access-Control-Allow-Origin": "*",
9	  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, webhook-id, webhook-signature, webhook-timestamp",
10	};
11	
12	Deno.serve(async (req) => {
13	  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
14	
15	  try {
16	    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
17	    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
18	    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
19	    const WEBHOOK_KEY = Deno.env.get("DODO_PAYMENTS_WEBHOOK_KEY") || Deno.env.get("DODO_PAYMENTS_WEBHOOK_SECRET");
20	
21	    if (!DODO_API_KEY) {
22	      console.error("DODO_PAYMENTS_API_KEY is not configured");
23	      await logSystemError({
24	        function_name: "dodo-webhook",
25	        error_type: "MISSING_CONFIG",
26	        severity: "critical",
27	        error_message: "DODO_PAYMENTS_API_KEY is not configured",
28	      });
29	      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
30	    }
31	    if (!WEBHOOK_KEY) {
32	      console.error("DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured");
33	      await logSystemError({
34	        function_name: "dodo-webhook",
35	        error_type: "MISSING_CONFIG",
36	        severity: "critical",
37	        error_message: "DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured",
38	      });
39	      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
40	    }
41	
42	    const rawBody = await req.text();
43	    const webhookHeaders = {
44	      "webhook-id": req.headers.get("webhook-id") || "",
45	      "webhook-signature": req.headers.get("webhook-signature") || "",
46	      "webhook-timestamp": req.headers.get("webhook-timestamp") || "",
47	    };
48	
49	    const dodo = new DodoPayments({
50	      bearerToken: DODO_API_KEY,
51	      webhookKey: WEBHOOK_KEY,
52	    });
53	
54	    let unwrapped: any;
55	    try {
56	      unwrapped = dodo.webhooks.unwrap(rawBody, { headers: webhookHeaders });
57	    } catch (e) {
58	      console.error("Invalid webhook signature", e);
59	      await logSystemError({
60	        function_name: "dodo-webhook",
61	        error_type: "WEBHOOK_VALIDATION",
62	        severity: "critical",
63	        error_message: errorToMessage(e),
64	        error_stack: errorToStack(e),
65	      });
66	      return new Response("Invalid signature", { status: 401, headers: corsHeaders });
67	    }
68	
69	    const eventType: string = unwrapped.type || "unknown";
70	    const payload: Record<string, unknown> = unwrapped.data || {};
71	    const webhookId = webhookHeaders["webhook-id"];
72	
73	    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
74	
75	    // Idempotency: skip if we've already processed this exact webhook-id
76	    if (webhookId) {
77	      const { data: dupList } = await supabase
78	        .from("subscription_webhooks")
79	        .select("id")
80	        .eq("gateway", "dodo")
81	        .eq("webhook_id", webhookId)
82	        .limit(1);
83	      if (dupList && dupList.length > 0) {
84	        console.log(`Duplicate webhook ${webhookId}, skipping`);
85	        return new Response("OK", { status: 200, headers: corsHeaders });
86	      }
87	    }
88	
89	    const subscriptionIdForLog = (payload["subscription_id"] as string | undefined) || null;
90	
91	    // Log the event (unprocessed)
92	    const logInsert = await supabase
93	      .from("subscription_webhooks")
94	      .insert({
95	        event_type: eventType,
96	        payload: unwrapped,
97	        gateway: "dodo",
98	        processed: false,
99	        dodo_subscription_id: subscriptionIdForLog,
100	        webhook_id: webhookId || null,
101	      })
102	      .select("id")
103	      .single();
104	
105	    const logId: string | null = logInsert.data?.id ?? null;
106	
107	    async function markProcessed(userId?: string | null) {
108	      if (!logId) return;
109	      await supabase
110	        .from("subscription_webhooks")
111	        .update({ processed: true, user_id: userId ?? null })
112	        .eq("id", logId);
113	    }
114	
115	    // Prefer correlation via metadata.local_payment_id (set at checkout creation)
116	    const meta = (payload["metadata"] as Record<string, string> | undefined) || {};
117	    const localPaymentId = (meta["local_payment_id"] as string | undefined) || null;
118	
119	    if (eventType === "payment.succeeded" || eventType === "payment_succeeded") {
120	      const paymentId = (payload["payment_id"] as string | undefined) || null;
121	
122	      let paymentRow: any = null;
123	      if (localPaymentId) {
124	        const { data } = await supabase.from("payments").select("*").eq("id", localPaymentId).single();
125	        paymentRow = data;
126	      } else if (paymentId) {
127	        const { data } = await supabase.from("payments").select("*").eq("dodo_payment_id", paymentId).single();
128	        paymentRow = data;
129	      }
130	
131	      if (paymentRow) {
132	        // Atomic status transition: only the first delivery wins (idempotent on retries)
133	        const { data: paidUpdate } = await supabase
134	          .from("payments")
135	          .update({
136	            status: "paid",
137	            ...(paymentId && !paymentRow.dodo_payment_id ? { dodo_payment_id: paymentId } : {}),
138	          })
139	          .eq("id", paymentRow.id)
140	          .neq("status", "paid")
141	          .select("id")
142	          .maybeSingle();
143	        const newlyPaid = !!paidUpdate;
144	
145	        if (newlyPaid) {
146	          // Increment credits atomically to prevent race conditions with verify-dodo-payment
147	          const creditField = paymentRow.plan_id ? "subscription_credits" : "topup_credits";
148	          await supabase.rpc("add_credits", {
149	            _user_id: paymentRow.user_id,
150	            _credit_field: creditField,
151	            _amount: paymentRow.credits_purchased,
152	          });
153	
154	          // Activate plan if applicable
155	          if (paymentRow.plan_id) {
156	            const { data: plan } = await supabase
157	              .from("plans")
158	              .select("name, billing_type")
159	              .eq("id", paymentRow.plan_id)
160	              .single();
161	
162	            if (plan) {
163	              const endsAt = new Date();
164	              if (plan.billing_type === "yearly") {
165	                endsAt.setFullYear(endsAt.getFullYear() + 1);
166	              } else {
167	                endsAt.setMonth(endsAt.getMonth() + 1);
168	              }
169	              await supabase
170	                .from("profiles")
171	                .update({
172	                  plan: plan.name,
173	                  subscription_ends_at: endsAt.toISOString(),
174	                  dodo_subscription_id: (payload["subscription_id"] as string | undefined) || null,
175	                })
176	                .eq("user_id", paymentRow.user_id);
177	            }
178	          }
179	        }
180	
181	        await markProcessed(paymentRow.user_id);
182	      }
183	    } else if (eventType === "payment.failed" || eventType === "payment_failed") {
184	      const paymentId = (payload["payment_id"] as string | undefined) || null;
185	      if (localPaymentId) {
186	        await supabase
187	          .from("payments")
188	          .update({ status: "failed", dodo_payment_id: paymentId })
189	          .eq("id", localPaymentId);
190	      } else if (paymentId) {
191	        await supabase.from("payments").update({ status: "failed" }).eq("dodo_payment_id", paymentId);
192	      }
193	      await markProcessed(null);
194	    } else if (eventType === "subscription.renewed" || eventType === "subscription_renewed") {
195	      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
196	      if (subscriptionId) {
197	        const { data: profile } = await supabase
198	          .from("profiles")
199	          .select("user_id, plan, credits, subscription_credits")
200	          .eq("dodo_subscription_id", subscriptionId)
201	          .single();
202	
203	        if (profile) {
204	          const { data: plan } = await supabase
205	            .from("plans")
206	            .select("credits, billing_type")
207	            .eq("name", profile.plan)
208	            .single();
209	
210	          if (plan) {
211	            const endsAt = new Date();
212	            if (plan.billing_type === "yearly") {
213	              endsAt.setFullYear(endsAt.getFullYear() + 1);
214	            } else {
215	              endsAt.setMonth(endsAt.getMonth() + 1);
216	            }
217	            // Renewal resets subscription_credits to plan amount (monthly allowance, not cumulative).
218	            // Only add the net delta to total credits so topup_credits and total stay accurate.
219	            const currentSub = (profile as any).subscription_credits ?? 0;
220	            const subDelta = plan.credits - currentSub;
221	            await supabase
222	              .from("profiles")
223	              .update({
224	                subscription_credits: plan.credits,
225	                credits: (profile.credits ?? 0) + subDelta,
226	                subscription_ends_at: endsAt.toISOString(),
227	              })
228	              .eq("user_id", profile.user_id);
229	          } else {
230	            // Plan not found — log critical error but extend subscription to avoid locking user out
231	            console.error(`Plan "${profile.plan}" not found for renewal. Subscription ${subscriptionId}`);
232	            await logSystemError({
233	              function_name: "dodo-webhook",
234	              error_type: "RENEWAL_PLAN_NOT_FOUND",
235	              severity: "critical",
236	              error_message: `Plan "${profile.plan}" not found for subscription renewal ${subscriptionId}`,
237	              user_id: profile.user_id,
238	            });
239	            const fallbackEndsAt = new Date();
240	            fallbackEndsAt.setMonth(fallbackEndsAt.getMonth() + 1);
241	            await supabase
242	              .from("profiles")
243	              .update({ subscription_ends_at: fallbackEndsAt.toISOString() })
244	              .eq("user_id", profile.user_id);
245	          }
246	        }
247	      }
248	      await markProcessed(null);
249	    } else if (
250	      eventType === "subscription.cancelled" ||
251	      eventType === "subscription_cancelled" ||
252	      eventType === "subscription.on_hold" ||
253	      eventType === "subscription.failed"
254	    ) {
255	      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
256	      if (subscriptionId) {
257	        // For on_hold/failed: downgrade immediately; for cancelled, let expiry task handle downgrade.
258	        if (eventType.includes("on_hold") || eventType.includes("failed")) {
259	          await supabase
260	            .from("profiles")
261	            .update({
262	              plan: "free",
263	              dodo_subscription_id: null,
264	              subscription_ends_at: null,
265	            })
266	            .eq("dodo_subscription_id", subscriptionId);
267	        }
268	      }
269	      await markProcessed(null);
270	    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
271	      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
272	      if (subscriptionId && localPaymentId) {
273	        const { data: payment } = await supabase.from("payments").select("user_id").eq("id", localPaymentId).single();
274	        if (payment) {
275	          await supabase.from("profiles").update({ dodo_subscription_id: subscriptionId }).eq("user_id", payment.user_id);
276	          await markProcessed(payment.user_id);
277	        }
278	      }
279	    }
280	
281	    return new Response("OK", { status: 200, headers: corsHeaders });
282	  } catch (err) {
283	    console.error("dodo-webhook error:", err);
284	    await logSystemError({
285	      function_name: "dodo-webhook",
286	      error_type: "PAYMENT_ERROR",
287	      severity: "critical",
288	      error_message: errorToMessage(err),
289	      error_stack: errorToStack(err),
290	    });
291	    return new Response("Internal error", { status: 500, headers: corsHeaders });
292	  }
293	});
